shots.draw_js:
clearScene();setBig(null);
setEq("$$C=\\frac{4\\varepsilon\\gamma}{(1-\\gamma)^2}$$","top");
note("算算它给多大的步子",640,320,"y lg");
setCap("论证完成了。现在把<b>数</b>代进去，看这套理论能不能真的用来跑算法。");

clearScene();setEq(null);
setBig("照着定理走就行","有理论保证的算法当然能跑");
setCap("保证是真的。<b>按它走的步子</b>小到策略几乎不动。");

clearScene();setBig(null);setEq(null);
lamps({y:270,gap:330,items:[
  {label:"γ=0.9",sub:"360ε",state:"on"},
  {label:"γ=0.99",sub:"39600ε",state:"dead"},
  {label:"γ=0.999",sub:"3996000ε",state:"dead"}]});
note("(1−γ)²",640,410,"sm");
setCap("γ 从 0.9 挪到 0.99，常数涨了 <b>110 倍</b>；再到 0.999，又涨 <b>101 倍</b>。");

clearScene();setBig(null);setEq(null);
fillBars({order:[0,1],step:760,vals:[stepOf(360),stepOf(1520)],
  x:400,y:420,w:480,h:170,max:0.0055,
  label:function(i){return ["γ=0.9","γ=0.95"][i];},
  cls:function(i){return i===0?"y":"r";},
  fmt:function(v){return v.toFixed(5);}});
note("允许的步长",640,462,"sm");
setCap("最优步长 = 斜率 ÷ (2C)，<b>与 C 成反比</b>。γ 只挪了 0.05，步长缩到 <b>¼</b>。");

clearScene();setBig(null);setEq(null);
lamps({y:280,gap:330,items:[
  {label:"保证对吗",sub:"对",state:"on"},
  {label:"能算出来吗",sub:"原则上能",state:"dead"},
  {label:"能用吗",sub:"步子太小",state:"dead"}]});
note("正确，但松到没有用",640,420,"r");
setCap("<b>指名反驳</b>：定理是对的，<b>按它走太慢</b> —— 于是 C 被扔掉。");

clearScene();setBig(null);setEq(null);
lamps({y:280,gap:340,items:[
  {label:"惩罚形式",sub:"减去 C·KL",state:"dead"},
  {label:"约束形式",sub:"KL ≤ δ",state:"on"}]});
note("TRPO 选了右边",640,420,"y");
setCap("C 没法用。但换掉的不只是 C —— <b>整个「惩罚」的形式都被换掉了</b>。");

clearScene();setEq(null);
setBig("把 C 调小就行","反正它已经是超参数了");
setCap("<b>不够</b>。固定的 C 会让步长<b>随梯度大小一起变</b>。");

clearScene();setBig(null);
setEq("$$\\max_\\pi\\ L(\\pi)-C\\,D_{KL}\\qquad\\text{vs.}\\qquad \\max_\\pi\\ L(\\pi)\\ \\ \\text{s.t.}\\ \\ D_{KL}\\le\\delta$$","top");
note("单次求解上二者等价",640,320,"sm lg");
note("差别在参数能不能搬",640,378,"y lg");
setCap("两种形式在<b>单次求解</b>上等价。差别在于<b>参数跨情形还管不管用</b>。");

clearScene();setBig(null);setEq(null);
morphBars({from:[0.05,0.10,0.20],to:[0.10,0.10,0.10],
  x:380,y:420,w:520,h:160,max:0.24,dur:1500,
  label:function(i){return ["弱","中","强"][i];},
  cls:function(i){return "y";},
  fmt:function(v){return v.toFixed(2);}});
note("三种梯度强度下的步长",640,462,"sm");
setCap("<b>固定 C</b>：步长跟着梯度放大。<b>固定 δ</b>：三根<b>拉平</b>。");

clearScene();setBig(null);setEq(null);
lamps({y:280,gap:330,items:[
  {label:"步长可控",sub:"δ 说了算",state:"on"},
  {label:"参数可搬",sub:"跨任务能用",state:"on"},
  {label:"定理保证",sub:"没有了",state:"dead"}]});
note("换来的和付出的",640,420,"y");
setCap("<b>指名反驳</b>：换的是<b>形式</b>，不是数值。代价是<b>那条定理不再罩着它</b>。");

clearScene();setBig(null);setEq(null);
lamps({y:270,gap:250,items:[
  {label:"状态求和",sub:"→ 采样",state:"dead"},
  {label:"动作求和",sub:"→ 重要性采样",state:"dead"},
  {label:"优势 A",sub:"→ Q",state:"dead"},
  {label:"max KL",sub:"→ 平均",state:"dead"}]});
note("讲座只列前三",640,410,"sm");
setCap("从纸上的目标到能跑的代码，中间隔着<b>四处代换</b>。");

clearScene();setEq(null);
setBig("TRPO 是那条定理的实现","照着单调改进定理写成代码");
setCap("讲座自己的措辞是 <b>inspired by</b> —— <b>受它启发</b>，不是实现它。");

clearScene();setBig(null);
setEq("$$\\max_\\theta\\ \\hat{\\mathbb{E}}_{s,a\\sim\\pi_{\\mathrm{old}}}\\!\\left[\\frac{\\pi_\\theta(a|s)}{\\pi_{\\mathrm{old}}(a|s)}\\,\\hat{A}(s,a)\\right]\\quad \\text{s.t.}\\quad \\hat{\\mathbb{E}}_s\\big[D_{KL}\\big]\\le\\delta$$","top");
note("每一项都能从一批轨迹里算出来",640,330,"g lg");
setCap("代换之后的样子：<b>每一项都只用旧策略的数据</b>。");

clearScene();setBig(null);setEq(null);
fillBars({order:[0,1,2,3,4],step:280,
  vals:[-0.4190,-0.4190,-0.4190,-0.4190,-0.4190],
  x:330,y:350,w:620,h:150,max:0.55,
  label:function(i){return ["π¹","π²","π³","π⁴","π⁵"][i];},
  cls:function(i){return "g";},
  fmt:function(v){return v.toFixed(4);}});
note("用 Q 的目标 − 用 A 的目标",640,392,"sm");
setCap("五个不同的候选策略，两个目标的差<b>完全相同</b> —— 所以 argmax 相同。");

clearScene();setBig(null);setEq(null);
lamps({y:270,gap:250,items:[
  {label:"前三代换",sub:"解不变",state:"on"},
  {label:"信赖域形状",sub:"来自定理",state:"on"},
  {label:"C→δ",sub:"保证没了",state:"dead"},
  {label:"max→平均",sub:"问题变了",state:"dead"}]});
note("定理与工程的分界线",640,410,"y");
setCap("<b>指名反驳</b>：TRPO 是<b>受启发</b>的工程化。分清哪部分是定理、哪部分不是。");
